sys_script_include.script:
var RaaSUtils = Class.create();
RaaSUtils.prototype = {
    initialize: function() {
    },
	referenceQualifierMedia() {
		var moviesNotToBeShown = []
		var grReview = new GlideRecord('x_1593670_raas_review');
		//opened by me 
		grReview.addEncodedQuery('opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4')
		grReview.query();
		while(grReview.next()) {
			moviesToBeShown.push(grReview.media.sys_id.toString())
		}

		var moviesToBeShown = []
		var grMedias = new GlideRecord('x_1593670_raas_media')
		grMedias.addQuery('state', '3');
		grMedias.query();
		//pra cada media completa eu vi se ela faz parte da lista de moviesNotBeShown e se ela não fizer dai ela entra na lista final
		while(grMedias.next()) {
			//-1 quer dizer q não existe
			if(moviesNotToBeShown.indexOf(grMedias.getUniqueValue()) == -1) {
				moviesToBeShown.push(grMedias.getUniqueValue())
			}
		}
		//in é tipo like
		return "sys_idIN" + moviesToBeShown.join(',')
	},

    type: 'RaaSUtils'
};
